-- La portada de cada programa del catálogo, como clave hacia el origen de medios.
--
-- **Generado desde `program-covers.json`. No editar a mano.**
-- Los checksums de aquí son los bytes que alguien revisó; escribir uno a mano rompería el
-- único vínculo entre lo aprobado y lo que se sirve.
--
-- Correr después de `001_global_training_catalogue.sql`: cada fila referencia un programa
-- que ese archivo crea.
--
-- **Actualiza en conflicto**, igual que las demostraciones y por la misma razón: la clave
-- es el contenido, así que un arte nuevo es una dirección nueva, y una fila que se quedara
-- apuntando a la vieja pediría un objeto que el siguiente despliegue ya no lleva.

\set ON_ERROR_STOP on

begin;

create temporary table curated_program_cover (
  program_id uuid,
  object_key text,
  content_type text,
  width integer,
  height integer,
  byte_size integer,
  checksum text
) on commit drop;

